    { name = "BattleState:markFoeParticipants", kind = "method", text = {
      "function BattleState:markFoeParticipants()",
      "  if not self:isDouble() then return end",
      "  local mine = self.sides and self.sides[1] and self.sides[1].battlers",
      "  local theirs = self.sides and self.sides[2] and self.sides[2].battlers",
      "  if not (mine and theirs) then return end",
      "  self.foeParticipants = self.foeParticipants or {}",
      "  for f = 1, 2 do",
      "    local foe = theirs[f]",
      "    if foe and foe.mon and (foe.mon.hp or 0) > 0 then",
      "      local set = self.foeParticipants[foe.mon] or {}",
      "      self.foeParticipants[foe.mon] = set",
      "      for m = 1, 2 do",
      "        local b = mine[m]",
      "        if b and b.mon and (b.mon.hp or 0) > 0 then set[b.mon] = true end",
      "      end",
      "    end",
      "  end",
      "end",
    } },
